import syntaxHighlight from "@11ty/eleventy-plugin-syntaxhighlight";
import markdownItAnchor from "markdown-it-anchor";

export default function (eleventyConfig) {
  // src/docs/nixops/ is git-ignored (regenerated by sync-docs) — but 11ty
  // honours .gitignore by default and would skip it. Disable that.
  eleventyConfig.setUseGitIgnore(false);

  eleventyConfig.addPlugin(syntaxHighlight);

  eleventyConfig.amendLibrary("md", (md) => {
    md.use(markdownItAnchor, {
      permalink: markdownItAnchor.permalink.headerLink(),
      level: [2, 3, 4],
    });
    md.set({ html: true, linkify: true, typographer: true });
  });

  eleventyConfig.addPassthroughCopy({ "src/assets": "assets" });

  eleventyConfig.addCollection("nixopsDocs", (api) =>
    api
      .getFilteredByTag("nixops-docs")
      .sort((a, b) => (a.data.order ?? 0) - (b.data.order ?? 0))
  );

  eleventyConfig.addFilter("stripLeadingNumber", (str) =>
    (str ?? "").replace(/^\d+[-_.]?/, "")
  );

  eleventyConfig.addFilter("titleFromSlug", (slug) => {
    const s = (slug ?? "").replace(/^\d+[-_.]?/, "").replace(/[-_]/g, " ");
    return s.charAt(0).toUpperCase() + s.slice(1);
  });

  return {
    dir: {
      input: "src",
      output: "_site",
      includes: "_includes",
      data: "_data",
    },
    markdownTemplateEngine: "njk",
    htmlTemplateEngine: "njk",
    templateFormats: ["njk", "md", "html", "11ty.js"],
  };
}
